import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Importing Docker Compose","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compose.md","filePath":"guide/compose.md"}'),i={name:"guide/compose.md"};function s(n,e,c,d,p,l){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="importing-docker-compose" tabindex="-1">Importing Docker Compose <a class="header-anchor" href="#importing-docker-compose" aria-label="Permalink to &quot;Importing Docker Compose&quot;">​</a></h1><p>Orbit reads a Compose file from a repository (<code>compose.yaml</code>, <code>compose.yml</code>, <code>docker-compose.yml</code> or <code>docker-compose.yaml</code> at the root, or a path you give) or from a pasted or uploaded file, and shows a plan to review before anything is created.</p><h2 id="creates" tabindex="-1">What it creates <a class="header-anchor" href="#creates" aria-label="Permalink to &quot;What it creates {#creates}&quot;">​</a></h2><ul><li><strong>Databases:</strong> PostgreSQL, MySQL (and MariaDB), MongoDB and Redis (and Valkey) images become managed databases on the version Orbit runs. They start empty: data in the Compose volumes is not migrated. Back it up with the old setup and restore it into the new database if you need it.</li><li><strong>Applications and workers:</strong> a service with a port becomes an application, without one a worker. A <code>build:</code> at the repository root with its <code>Dockerfile</code> is built by Orbit from the repository. Anything else needs a container image, which the review asks for.</li><li><strong>Variables:</strong> they are copied, and names that look secret become secrets. Values that point to a database become references, and URLs that point to another service are rewritten to its address inside the environment.</li></ul><h2 id="not-kept" tabindex="-1">What it does not keep <a class="header-anchor" href="#not-kept" aria-label="Permalink to &quot;What it does not keep {#not-kept}&quot;">​</a></h2><p>Application volumes, <code>env_file</code>, networks, <code>privileged</code>, capabilities, devices, Compose secrets and configs. The review lists each one, and instances are set in Settings afterwards.</p><h2 id="after" tabindex="-1">After the import <a class="header-anchor" href="#after" aria-label="Permalink to &quot;After the import {#after}&quot;">​</a></h2><p>Each service is an ordinary application, worker or database. Nothing ties them to the file anymore, so later changes to it are not picked up.</p>',8)])])}const f=o(i,[["render",s]]);export{m as __pageData,f as default};
